import re
from flask import Flask, request, jsonify

app = Flask(__name__)


def safe_eval(expression: str) -> str:
    """Evaluate a simple arithmetic expression safely.

    Only allows integers, floats, and the operators +, -, *, /, **.
    Parentheses are allowed for grouping.
    """
    # Remove all whitespace to simplify parsing
    expr = expression.replace(" ", "")
    if not expr:
        raise ValueError("Empty expression")

    # Allow only digits, decimal points, operators, and parentheses
    # Pattern: numbers (int or float), operators + - * / **, and parentheses
    allowed_chars_regex = r"^[0-9+\-*/().\s]+$"
    if not re.match(allowed_chars_regex, expr):
        raise ValueError("Invalid characters in expression")

    # Further sanitize: disallow leading operators, consecutive operators,
    # and ensure the expression is well-formed.
    # We'll use a simple check: after removing spaces, the string must
    # match a basic arithmetic pattern.
    # Allowing ** for exponentiation.

    # Evaluate using Python's eval, but in a restricted context.
    # Since we already validated characters, the main risk is code injection
    # via strings like "__import__('os')". Our regex blocks letters, so
    # it's safe.
    try:
        result = eval(expr, {"__builtins__": None}, {})
    except Exception as e:
        raise ValueError(f"Evaluation error: {e}")

    # Ensure result is a number
    if not isinstance(result, (int, float)):
        raise ValueError("Result is not a number")

    # Return as string, matching the schema example "7"
    # If it's a float that is an integer value, return int-like string
    if isinstance(result, float) and result == int(result):
        return str(int(result))
    return str(result)


@app.route("/calculator", methods=["POST"])
def calculator():
    data = request.get_json(silent=True)
    if not data or "expression" not in data:
        return jsonify({"error": "Invalid input"}), 400

    expression = data.get("expression")
    if not isinstance(expression, str):
        return jsonify({"error": "Invalid input"}), 400

    try:
        result = safe_eval(expression)
        return jsonify({"result": result}), 200
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        return jsonify({"error": "Internal server error"}), 500


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
